  "jk_w03_6": ["DAD", "Why did the vac truck get a promotion? It was great at picking up the slack.", 5.71, "audio/lines/jokes/jk_w03_6.mp3"],
  "jk_w03_7": ["DAD", "Why are pipes so calm? They just go with the flow.", 4.68, "audio/lines/jokes/jk_w03_7.mp3"],
  "jk_w03_8": ["DAD", "I'd tell you a joke about the oil sands, but it's a little crude.", 4.99, "audio/lines/jokes/jk_w03_8.mp3"],
