  "jk_w04_2": ["DAD", "How does a snowman get to work? By icicle.", 4.34, "audio/lines/jokes/jk_w04_2.mp3"],
  "jk_w04_3": ["DAD", "I told a train joke on the LRT. Nobody laughed. Wrong platform, I guess.", 7.25, "audio/lines/jokes/jk_w04_3.mp3"],
