  "jk_w04_5": ["DAD", "I'd tell you a skating joke, but I'm already on thin ice.", 4.73, "audio/lines/jokes/jk_w04_5.mp3"],
  "jk_w04_6": ["DAD", "Why did the crane operator get a raise? He really lifted the team.", 5.47, "audio/lines/jokes/jk_w04_6.mp3"],
  "jk_w04_7": ["DAD", "Why do the river valley trails never get stressed? They just keep winding down.", 5.95, "audio/lines/jokes/jk_w04_7.mp3"],
  "jk_w04_8": ["DAD", "Why did the actor fall through the floor? It was just a stage he was going through.", 6.62, "audio/lines/jokes/jk_w04_8.mp3"],
  "jk_w04_castle": ["DAD", "Busy kitchen tonight. Even the potatoes are mashed and the eggs are beat.", 5.57, "audio/lines/jokes/jk_w04_castle.mp3"],
  "jk_w04_fort": ["DAD", "Me and rollercoasters? We've had our ups and downs.", 4.78, "audio/lines/jokes/jk_w04_fort.mp3"],
  "jk_w04_secret": ["DAD", "A jungle in a pyramid? I don't see the point. ...Oh. There it is. On top.", 8.35, "audio/lines/jokes/jk_w04_secret.mp3"],
