  "jk_w05_2": ["DAD", "Pancake breakfast? I'm so excited, I'm flipping out.", 5.35, "audio/lines/jokes/jk_w05_2.mp3"],
  "jk_w05_3": ["DAD", "Why did the cowboy get a wiener dog? He wanted to get a long little doggie.", 5.76, "audio/lines/jokes/jk_w05_3.mp3"],
  "jk_w05_4": ["DAD", "What do you call a wagon full of jokes? A chuckle-wagon.", 4.9, "audio/lines/jokes/jk_w05_4.mp3"],
  "jk_w05_5": ["DAD", "Why do they call it the Peace Bridge? Because it's still in one piece.", 5.23, "audio/lines/jokes/jk_w05_5.mp3"],
  "jk_w05_6": ["DAD", "What do you call a sleeping dinosaur? A dino-snore.", 4.61, "audio/lines/jokes/jk_w05_6.mp3"],
  "jk_w05_7": ["DAD", "I told a joke at the top of the Calgary Tower. Went right over everybody's head.", 6.29, "audio/lines/jokes/jk_w05_7.mp3"],
  "jk_w05_8": ["DAD", "The ski jump's great. Trust me, it's all downhill from here.", 5.83, "audio/lines/jokes/jk_w05_8.mp3"],
  "jk_w05_castle": ["DAD", "What do you call a bull taking a nap? A bulldozer.", 4.46, "audio/lines/jokes/jk_w05_castle.mp3"],
