  "w01_glitchy_02": ["GLITCHY", "Beep! Boop-boop!", 2.64, "audio/lines/w01/w01_glitchy_02.mp3"],
  "w01_kinan_01": ["KINAN", "It's my birthday! I'm eleven! ...Ooh. What's in the garage?", 6.79, "audio/lines/w01/w01_kinan_01.mp3"],
  "w01_kinan_02": ["KINAN", "Do not open, Kinan. ...Okay. One tiny peek.", 5.86, "audio/lines/w01/w01_kinan_02.mp3"],
  "w01_kinan_03": ["KINAN", "Whoa! Hey! Come back here, little guy!", 5.21, "audio/lines/w01/w01_kinan_03.mp3"],
  "w01_kinan_04": ["KINAN", "But Mom, my socks are walking!", 3.17, "audio/lines/w01/w01_kinan_04.mp3"],
  "w01_kinan_05": ["KINAN", "Okay, socks. You're going down.", 4.06, "audio/lines/w01/w01_kinan_05.mp3"],
  "w01_kinan_06": ["KINAN", "Couch hills? Coffee-table mountains? I've got this!", 5.86, "audio/lines/w01/w01_kinan_06.mp3"],
  "w01_kinan_07": ["KINAN", "Breakfast is attacking me. Rude.", 3.84, "audio/lines/w01/w01_kinan_07.mp3"],
  "w01_kinan_08": ["KINAN", "My brick city! Don't you dare knock it over, Glitchy!", 5.28, "audio/lines/w01/w01_kinan_08.mp3"],
  "w01_kinan_09": ["KINAN", "Sprinklers, squirrels and slopes. Classic front yard.", 5.86, "audio/lines/w01/w01_kinan_09.mp3"],
  "w01_kinan_10": ["KINAN", "Smile for the picture? I'm smiling! I'm running and smiling!", 6.41, "audio/lines/w01/w01_kinan_10.mp3"],
  "w01_kinan_11": ["KINAN", "Chenoa's art room! Don't touch the paint. ...Touching the paint.", 6.22, "audio/lines/w01/w01_kinan_11.mp3"],
  "w01_kinan_12": ["KINAN", "String lights and patio food. Smells like birthday dinner!", 5.57, "audio/lines/w01/w01_kinan_12.mp3"],
  "w01_kinan_13": ["KINAN", "Pelican taxi? Yes, please!", 4.03, "audio/lines/w01/w01_kinan_13.mp3"],
  "w01_kinan_15": ["KINAN", "Ginger! You're awake! Wanna help me catch a glitch?", 5.57, "audio/lines/w01/w01_kinan_15.mp3"],
  "w01_kinan_16": ["KINAN", "Chikastino! Good boy! Let's go, let's go!", 5.62, "audio/lines/w01/w01_kinan_16.mp3"],
  "w01_kinan_17": ["KINAN", "Baby Fin! My singing shark! I had this when I was one!", 6.34, "audio/lines/w01/w01_kinan_17.mp3"],
  "w01_kinan_18": ["KINAN", "He jumped in the school bus! Wait for me!", 4.27, "audio/lines/w01/w01_kinan_18.mp3"],
  "w01_kinan_19": ["KINAN", "It's my birthday! I'm eleven!", 3.7, "audio/lines/w01/w01_kinan_19.mp3"],
  "w01_kinan_20": ["KINAN", "Ready or not, Glitchy, here I come!", 3.77, "audio/lines/w01/w01_kinan_20.mp3"],
  "w01_mom_01": ["MOM", "Kinan! Nobody leaves this house until your room is clean.", 5.06, "audio/lines/w01/w01_mom_01.mp3"],
  "w01_mom_02": ["MOM", "Then catch them. Clean. Your. Room.", 6.31, "audio/lines/w01/w01_mom_02.mp3"],
  "w01_mom_12": ["MOM", "Kinan, NO!", 2.02, "audio/lines/w01/w01_mom_12.mp3"],
  "w01_shad_01": ["SHAD", "Kinan... did you open it?!", 2.45, "audio/lines/w01/w01_shad_01.mp3"],
