  "w02_glitchy_02": ["GLITCHY", "Bzzt! Beep!", 2.95, "audio/lines/w02/w02_glitchy_02.mp3"],
  "w02_kinan_01": ["KINAN", "He's in my school? On my birthday?", 3.74, "audio/lines/w02/w02_kinan_01.mp3"],
  "w02_kinan_02": ["KINAN", "I've got this, guys. ...Okay, maybe you can help a little.", 5.42, "audio/lines/w02/w02_kinan_02.mp3"],
  "w02_kinan_03": ["KINAN", "Bus roofs are basically sidewalks, right?", 3.74, "audio/lines/w02/w02_kinan_03.mp3"],
  "w02_kinan_04": ["KINAN", "Shh, library voice. ...Whoa, these shelves are tall!", 5.3, "audio/lines/w02/w02_kinan_04.mp3"],
  "w02_kinan_05": ["KINAN", "Pudding puddles. Don't slip. Don't slip. Don't...", 6.53, "audio/lines/w02/w02_kinan_05.mp3"],
  "w02_kinan_06": ["KINAN", "Monkey bars, then the big slide. Recess, here I come!", 5.93, "audio/lines/w02/w02_kinan_06.mp3"],
  "w02_kinan_07": ["KINAN", "So many mittens. Who loses this many mittens?", 4.85, "audio/lines/w02/w02_kinan_07.mp3"],
  "w02_kinan_08": ["KINAN", "Vader! What are you doing in the library? Reading? Okay, come on.", 7.44, "audio/lines/w02/w02_kinan_08.mp3"],
  "w02_kinan_09": ["KINAN", "My Whirl Spinner! I used to spin this for hours when I was two!", 5.64, "audio/lines/w02/w02_kinan_09.mp3"],
  "w02_kinan_10": ["KINAN", "Long story. Follow that radio!", 4.08, "audio/lines/w02/w02_kinan_10.mp3"],
  "w02_milo_01": ["MILO", "Whoa, is that a living bug? That's the coolest thing I've ever seen.", 5.71, "audio/lines/w02/w02_milo_01.mp3"],
  "w02_milo_02": ["MILO", "Magnets! Flip the circuit and the door opens. Science!", 6.24, "audio/lines/w02/w02_milo_02.mp3"],
  "w02_milo_03": ["MILO", "His pixels are leaking out of the screens. So cool. Also scary.", 6.84, "audio/lines/w02/w02_milo_03.mp3"],
  "w02_milo_04": ["MILO", "We're coming with you. Need something built? Call me.", 5.4, "audio/lines/w02/w02_milo_04.mp3"],
